37	static void UI_DrawButton(uint16_t x, uint16_t y, uint16_t w, uint16_t h,
38	                          uint32_t bg_color, uint32_t border_color, uint32_t text_color,
39	                          sFONT *font, const char *label)
40	{
41	    /* 1. Nen nut */
42	    BSP_LCD_SetTextColor(bg_color);
43	    BSP_LCD_FillRect(x, y, w, h);
44	
45	    /* 2. Khung vien nut ro net */
46	    BSP_LCD_SetTextColor(border_color);
47	    BSP_LCD_DrawRect(x, y, w, h);
48	    BSP_LCD_DrawRect(x + 1, y + 1, w - 2, h - 2);
49	
50	    /* 3. Can chu o chinh giua hop nut */

 51	    uint32_t len = 0;
 52	    while (label[len] != '\0') {
 53	        len++;
 54	    }
 55	    uint16_t text_width = len * font->Width;
 56	    uint16_t text_x = x + ((w > text_width) ? ((w - text_width) / 2) : 0);
 57	    uint16_t text_y = y + ((h > font->Height) ? ((h - font->Height) / 2) : 0);
 58	
 59	    BSP_LCD_SetBackColor(bg_color);
 60	    BSP_LCD_SetTextColor(text_color);
 61	    BSP_LCD_SetFont(font);
 62	    BSP_LCD_DisplayStringAt(text_x, text_y, (uint8_t *)label, LEFT_MODE);
 63	}
